"""Tiny INI-like parser.

[section] headers; `key = value` lines; blank lines and lines starting with # or ; ignored.
Inline comments start at an unquoted ' #' or ' ;'. Values may be wrapped in double quotes,
which are removed and protect # ; = inside. Keys are case-insensitive (lowercased).
A repeated key in the same section overrides the earlier value.
Keys before any section go into section "".
"""


def _split_key_value(line):
    """Split on the first unquoted '='; return (key, rest) or None."""
    in_quote = False
    for i, c in enumerate(line):
        if c == '"':
            in_quote = not in_quote
        elif c == "=" and not in_quote:
            return line[:i], line[i + 1:]
    return None


def _parse_value(raw):
    raw = raw.strip()
    if raw.startswith('"'):
        end = raw.find('"', 1)
        if end != -1:
            return raw[1:end]
        return raw[1:]  # unterminated: keep the rest literally
    cut = len(raw)
    for i, c in enumerate(raw):
        if c in "#;" and i > 0 and raw[i - 1] == " ":
            cut = i
            break
    return raw[:cut].strip()


def parse(text):
    out, sec = {"": {}}, ""
    for line in text.splitlines():
        line = line.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            sec = line[1:-1]
            out.setdefault(sec, {})
            continue
        split = _split_key_value(line)
        if split is None:
            continue
        k, v = split
        out[sec][k.strip().lower()] = _parse_value(v)
    return out

