from cfg.parser import parse


def test_basic():
    assert parse("[a]\nx = 1\n") == {"": {}, "a": {"x": "1"}}


def test_inline_comments():
    assert parse("[a]\nx = 1 # trailing\ny = 2 ; also trailing\n") == {"": {}, "a": {"x": "1", "y": "2"}}


def test_inline_comment_requires_space():
    assert parse("[a]\nurl = http://x.com/p?k=v # note\nhash = a#b\n") == {"": {}, "a": {"url": "http://x.com/p?k=v", "hash": "a#b"}}


def test_quoted_value_protects_specials():
    assert parse('[a]\nq = "a # b ; c = d"\n') == {"": {}, "a": {"q": "a # b ; c = d"}}


def test_repeated_key_last_wins():
    assert parse("[a]\nx = 1\nx = 2\n") == {"": {}, "a": {"x": "2"}}


def test_keys_lowercased():
    assert parse("[a]\nFoo = bar\n") == {"": {}, "a": {"foo": "bar"}}

